public class Vec2Test {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("plus", new Vec2(2.0, 5.0), new Vec2(1.5, 2.0).plus(new Vec2(0.5, 3.0)));
        check("plus with negatives", new Vec2(3.0, 0.0), new Vec2(2.25, -1.0).plus(new Vec2(0.75, 1.0)));
        check("scaled by 2.0", new Vec2(3.0, -4.0), new Vec2(1.5, -2.0).scaled(2.0));
        check("scaled by 0.5", new Vec2(2.5, 1.5), new Vec2(5.0, 3.0).scaled(0.5));
        check("dot product", 4.0, new Vec2(1.5, 2.0).dot(new Vec2(2.0, 0.5)));
        check("dot of perpendicular vectors", 0.0, new Vec2(1.0, 0.0).dot(new Vec2(0.0, 3.0)));
        check("zero factory", new Vec2(0.0, 0.0), Vec2.zero());
        Vec2 original = new Vec2(1.0, 1.0);
        original.plus(new Vec2(9.0, 9.0));
        check("plus does not mutate the receiver", new Vec2(1.0, 1.0), original);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

